import json
import itertools

def solve():
    houses = [0, 1, 2]  # indices for houses 1..3 (left to right)
    names = ['Eric', 'Peter', 'Arnold']
    mothers = ['Holly', 'Aniya', 'Janelle']
    foods = ['pizza', 'grilled cheese', 'spaghetti']

    def pos_of(value_list, house_assignment, value):
        # house_assignment is a tuple/list of values per house index
        for i, v in enumerate(house_assignment):
            if v == value:
                return i
        return None

    solutions = []

    for name_perm in itertools.permutations(names):
        # name_perm[h] gives name at house h
        # Constraint 3 ties Eric to grilled cheese; we'll check with food after assigning foods
        for mother_perm in itertools.permutations(mothers):
            # mother_perm[h] gives mother at house h
            # Constraint 4: Peter's mother is Holly
            house_peter = name_perm.index('Peter')
            if mother_perm[house_peter] != 'Holly':
                continue

            for food_perm in itertools.permutations(foods):
                # food_perm[h] gives food at house h

                # Constraint 3: The grilled cheese eater is Eric.
                house_grilled = food_perm.index('grilled cheese')
                if name_perm[house_grilled] != 'Eric':
                    continue

                # Constraint 2: grilled cheese eater is directly left of Aniya's child
                house_aniya = mother_perm.index('Aniya')
                if house_grilled + 1 != house_aniya:
                    continue

                # Constraint 1 (interpreted as): The spaghetti eater and Peter are next to each other.
                house_spaghetti = food_perm.index('spaghetti')
                if abs(house_spaghetti - house_peter) != 1:
                    continue

                # All constraints satisfied; record solution
                solutions.append((name_perm, mother_perm, food_perm))

    if len(solutions) != 1:
        # If multiple or zero solutions, raise an error to ensure correctness.
        raise ValueError(f"Expected exactly one solution, found {len(solutions)}")

    name_perm, mother_perm, food_perm = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Mother", "Food"],
            "rows": []
        }
    }

    for h in houses:
        result["solution"]["rows"].append([
            str(h + 1),
            name_perm[h],
            mother_perm[h],
            food_perm[h]
        ])

    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    solve()
